package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.RefreshTokenTtlSecondsVO;

class RefreshTokenTtlSecondsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of refresh token ttl seconds of tenant config")
  void test_refresh_token_ttl_seconds_value_holder_assign_plain_value() {
    Object holder = new Object();
    RefreshTokenTtlSecondsValueHolder<Object> value =
        new RefreshTokenTtlSecondsValueHolder<>(holder);
    Assertions.assertSame(holder, value.refreshTokenTtlSeconds(1),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRefreshTokenTtlSecondsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRefreshTokenTtlSeconds().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of refresh token ttl seconds of tenant config")
  void test_refresh_token_ttl_seconds_value_holder_assign_value_object() {
    Object holder = new Object();
    RefreshTokenTtlSecondsValueHolder<Object> value =
        new RefreshTokenTtlSecondsValueHolder<>(holder);
    RefreshTokenTtlSecondsVO vo = RefreshTokenTtlSecondsVO.from(1);
    Assertions.assertFalse(value.getRefreshTokenTtlSecondsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.refreshTokenTtlSeconds(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getRefreshTokenTtlSecondsValue().orElseThrow());
    Assertions.assertSame(holder, value.refreshTokenTtlSeconds(Optional.empty()));
    Assertions.assertFalse(value.getRefreshTokenTtlSecondsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.refreshTokenTtlSeconds(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRefreshTokenTtlSecondsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of refresh token ttl seconds of tenant config against the original")
  void test_refresh_token_ttl_seconds_value_holder_read() {
    Object holder = new Object();
    RefreshTokenTtlSecondsValueHolder<Object> value =
        new RefreshTokenTtlSecondsValueHolder<>(holder);
    RefreshTokenTtlSecondsVO vo = RefreshTokenTtlSecondsVO.from(1);
    RefreshTokenTtlSecondsVO other = RefreshTokenTtlSecondsVO.from(1);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getRefreshTokenTtlSecondsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRefreshTokenTtlSeconds(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRefreshTokenTtlSeconds(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.refreshTokenTtlSeconds(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRefreshTokenTtlSeconds(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRefreshTokenTtlSeconds(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of refresh token ttl seconds of tenant config")
  void test_refresh_token_ttl_seconds_value_holder_unset() {
    Object holder = new Object();
    RefreshTokenTtlSecondsValueHolder<Object> value =
        new RefreshTokenTtlSecondsValueHolder<>(holder);
    RefreshTokenTtlSecondsVO vo = RefreshTokenTtlSecondsVO.from(1);
    value.refreshTokenTtlSeconds(vo);
    Assertions.assertSame(holder,
        value.unsetRefreshTokenTtlSecondsIfMatches("refreshTokenTtlSeconds_other"));
    Assertions.assertTrue(value.getRefreshTokenTtlSecondsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetRefreshTokenTtlSecondsIfMatches("refreshTokenTtlSeconds"));
    Assertions.assertFalse(value.getRefreshTokenTtlSecondsValue().isPresent(),
        "The field name must clear the value");
    value.refreshTokenTtlSeconds(vo);
    Assertions.assertSame(holder, value.unsetRefreshTokenTtlSeconds());
    Assertions.assertFalse(value.getRefreshTokenTtlSecondsValue().isPresent(),
        "Unset must clear the value");
  }
}
